using System;
using EnglishLearning.DAL.Entities;
using Microsoft.EntityFrameworkCore;

namespace EnglishLearning.DAL.Data.Seeders;

public static class IdiomSeeder
{
    public static async Task SeedAsync(
        AppDbContext context,
        IReadOnlyDictionary<int, int> topicIds,
        CancellationToken cancellationToken = default)
    {
        var existingIdioms = await context.Idioms
            .AsNoTracking()
            .Select(idiom => new { idiom.Id, idiom.IdiomText, idiom.TopicId })
            .ToListAsync(cancellationToken);
        var seedByText = SeedData
            .GroupBy(seed => seed.IdiomText)
            .ToDictionary(group => group.Key, group => group.First());
        var existingTexts = existingIdioms.Select(idiom => idiom.IdiomText).ToHashSet();
        var topicsUpdated = false;

        foreach (var idiom in existingIdioms)
        {
            if (!seedByText.TryGetValue(idiom.IdiomText, out var seed) ||
                !topicIds.TryGetValue(seed.TopicId, out var mappedTopicId) ||
                idiom.TopicId == mappedTopicId)
                continue;

            var topicUpdate = new Idiom { Id = idiom.Id, TopicId = mappedTopicId };
            context.Idioms.Attach(topicUpdate);
            context.Entry(topicUpdate).Property(item => item.TopicId).IsModified = true;
            topicsUpdated = true;
        }

        var newIdioms = SeedData
            .Where(x => !existingTexts.Contains(x.IdiomText))
            .Select(x => new Idiom
            {
                IdiomText = x.IdiomText,
                TopicId = topicIds[x.TopicId],
                FirstLetter = x.FirstLetter,
                Phonetic = x.Phonetic,
                MeaningEn = x.MeaningEn,
                MeaningVi = x.MeaningVi,
                example_en = x.ExampleEn,
                example_vi = x.ExampleVi
            })
            .ToList();

        if (newIdioms.Count > 0)
            await context.Idioms.AddRangeAsync(newIdioms, cancellationToken);

        if (newIdioms.Count > 0 || topicsUpdated)
            await context.SaveChangesAsync(cancellationToken);
    }

    private sealed record SeedIdiom(
        int TopicId,
        string IdiomText,
        string FirstLetter,
        string Phonetic,
        string MeaningEn,
        string MeaningVi,
        string ExampleEn,
        string ExampleVi);

